// Per-label sanitization & 63-char RFC 1035 cap
const cleanLabel = rawLabel.replace(/[^a-z0-9-]/g, '').replace(/^-+|-+$/g, '');
if (!cleanLabel || cleanLabel.length > 63) return null;

// Full hostname 253-char limit (RFC 1035 Section 2.3.4)
const finalDomain = sanitizedPatLabels.join('.') + '.' + sanitizedExtLabels.join('.');
if (finalDomain.length > 253) return null;
